CREATE TABLE IF NOT EXISTS donation_pledges (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), campaign_id UUID REFERENCES campaigns(id), donor_name TEXT, donor_email TEXT NOT NULL, amount_cents BIGINT NOT NULL CHECK (amount_cents > 0), currency TEXT NOT NULL DEFAULT 'USD', message TEXT, status TEXT NOT NULL DEFAULT 'pledged' CHECK (status IN ('pledged','payment_pending','confirmed','refunded')), created_at TIMESTAMPTZ NOT NULL DEFAULT now());